insert into travelers (id,name,initial,hue,is_similar,quote,bio,tags,dims,trajectory) values
  (1,'林可','可',0,true,'转过来才发现，最难的不是学技能，是重建身份认同。','交互设计 → AI 产品经理',ARRAY['28 岁转型','边工作边尝试','设计背景','未降薪明显幅度']::text[],'[["我擅长","把模糊的想法拆成能落地的步骤"],["我喜欢","爬山 · 把混乱变有序"],["我是什么样的人","慢热，但认定了就很轴"],["我希望认识什么样的人","正在换赛道、心里没底的人"]]'::jsonb,'[{"age":"28 岁","t":"开始尝试转型 AI 产品","d":"利用下班时间学习和实践，在公司申请了一个小型 AI 项目，逐步承担更多产品职责。"},{"age":"30 岁","t":"转型产品经理","d":"降薪去创业公司，第一年被业务按在地上摩擦，但第一次为结果负责。"},{"age":"33 岁","t":"AI 产品负责人","d":"带 6 人小组做 AI 工具，设计背景成了最大的差异化优势。"}]'::jsonb),
  (2,'慢速行星','慢',2,true,'30 岁重新读本科，同学叫我姐。但我第一次觉得时间是自己的。','前运营，现心理学在读',ARRAY['30 重读本科','裸辞']::text[],'[["我擅长","把大目标切成每天能做完的小事"],["我喜欢","图书馆闭馆前的最后一小时"],["我是什么样的人","大器晚成型选手"],["我希望认识什么样的人","也在「重来一次」的人"]]'::jsonb,'[{"age":"24 岁","t":"专科毕业做运营","d":"六年换了四家公司，越做越熟练，也越做越空。"},{"age":"30 岁","t":"重读本科","d":"考了两次，读心理学。存款只够两年，但睡得着了。"}]'::jsonb),
  (3,'第七次日落','落',1,false,'裸辞第 200 天，存款减半，睡眠翻倍。','gap 中，正在环岛骑行',ARRAY['大厂裸辞','gap 一年']::text[],'[["我擅长","把日子过得便宜又有质感"],["我喜欢","海边的烂天气"],["我是什么样的人","用力过猛后学会松手的人"],["我希望认识什么样的人","敢浪费时间的人"]]'::jsonb,'[{"age":"27 岁","t":"大厂高级运营","d":"年终 3.75，代价是耳鸣和凌晨两点的地铁。"},{"age":"29 岁","t":"裸辞 gap","d":"没有计划的一年。骑行到第三个月，才停止每天打开招聘软件。"}]'::jsonb),
  (4,'晚风收集者','晚',4,true,'一个人做产品：白天写代码，晚上画图标，半夜回用户邮件。','独立开发者，产品月收入刚过房租',ARRAY['设计转独立开发','两年']::text[],'[["我擅长","一个人当一支队伍"],["我喜欢","发版后的第一条好评"],["我是什么样的人","悲观的行动派"],["我希望认识什么样的人","也在一个人做事的人"]]'::jsonb,'[{"age":"28 岁","t":"辞职做独立开发","d":"用设计功底做了三款小工具，死了两款，活下来的那款养活了自己。"}]'::jsonb),
  (5,'低电量诗人','诗',3,true,'从改需求到听人说话，我终于不用假装外向了。','前产品经理，现实习咨询师',ARRAY['转行心理咨询','35+']::text[],'[["我擅长","听出话背后的那句话"],["我喜欢","来访者说「被你说中了」的瞬间"],["我是什么样的人","内向但不冷"],["我希望认识什么样的人","35 岁以后才换方向的人"]]'::jsonb,'[{"age":"35 岁","t":"转行心理咨询","d":"读了三年在职硕士，时薪从 500 变成 0，又慢慢变回 300。"}]'::jsonb),
  (6,'折返跑者','折',0,false,'从咨询公司离开后，我把最擅长的访谈留了下来，转去做用户研究。','管理咨询 → 用户研究',ARRAY['咨询转用户研究','31 岁','深圳']::text[],'[["我擅长","从复杂信息里找到关键矛盾"],["我喜欢","深度访谈"],["我是什么样的人","理性但对人好奇"],["我希望认识什么样的人","想把通用能力迁移到新行业的人"]]'::jsonb,'[{"age":"27 岁","t":"进入管理咨询","d":"高强度项目让我快速成长，也让我开始在意工作与人的真实关系。"},{"age":"31 岁","t":"转型用户研究","d":"用访谈与行业分析经验进入互联网，从交付报告转向影响产品。"}]'::jsonb),
  (7,'北纬三十度','北',2,false,'离开大厂去大理，不是躺平，而是第一次自己定义生意和生活。','互联网运营 → 民宿主理人',ARRAY['运营转主理人','小城生活','34 岁']::text[],'[["我擅长","把体验变成可持续的小生意"],["我喜欢","认识来自不同城市的人"],["我是什么样的人","温和的冒险派"],["我希望认识什么样的人","认真考虑离开大城市的人"]]'::jsonb,'[{"age":"29 岁","t":"大厂运营负责人","d":"业务越做越大，但生活只剩会议与复盘。"},{"age":"34 岁","t":"搬到大理经营民宿","d":"从选址、改造到获客全部自己做，重新理解了工作与生活的边界。"}]'::jsonb),
  (8,'纸飞机','纸',4,false,'我没辞职学编程，而是先用公司里没人愿意整理的数据做了第一个项目。','财务分析 → 数据分析师',ARRAY['财务转数据','内部转岗','27 岁']::text[],'[["我擅长","把业务问题变成指标"],["我喜欢","自动化重复工作"],["我是什么样的人","谨慎的实践派"],["我希望认识什么样的人","想低风险转技术岗的人"]]'::jsonb,'[{"age":"25 岁","t":"财务共享中心","d":"重复报表占据了大部分时间，我开始用脚本自动化日常工作。"},{"age":"27 岁","t":"内部转岗数据分析","d":"用真实业务数据做作品集，在原公司完成了第一次岗位迁移。"}]'::jsonb),
  (9,'木棉','棉',1,false,'重新工作后，我没有隐藏全职妈妈的五年，那段经历训练了最真实的协调能力。','全职妈妈 → 生涯咨询师',ARRAY['重返职场','生涯咨询','36 岁']::text[],'[["我擅长","看见选择背后的现实约束"],["我喜欢","陪人找回行动感"],["我是什么样的人","柔软但有边界"],["我希望认识什么样的人","正在重返职场的女性"]]'::jsonb,'[{"age":"30 岁","t":"暂停工作照顾家庭","d":"五年里失去职业身份，也积累了对家庭分工和女性处境的理解。"},{"age":"36 岁","t":"成为生涯咨询师","d":"完成系统训练，从同伴互助开始逐步建立咨询案例。"}]'::jsonb),
  (10,'十点半','十',3,false,'建筑教会我处理复杂约束，UX 让我终于能更快看到设计是否真的有用。','建筑设计 → UX 设计师',ARRAY['建筑转 UX','作品集','29 岁']::text[],'[["我擅长","处理复杂系统与空间关系"],["我喜欢","快速验证设计"],["我是什么样的人","耐心的结构控"],["我希望认识什么样的人","从传统设计转数字产品的人"]]'::jsonb,'[{"age":"24 岁","t":"进入建筑事务所","d":"习惯了长周期项目与复杂协作，但很难及时得到用户反馈。"},{"age":"29 岁","t":"转型 UX 设计","d":"用半年完成三个真实项目，进入 SaaS 团队负责企业端体验。"}]'::jsonb),
  (11,'河岸书店','书',2,false,'四十岁开书店不是浪漫冲动，而是一份算过租金、库存和现金流的计划。','广告策划 → 独立书店主理人',ARRAY['广告转书店','40 岁','实体创业']::text[],'[["我擅长","策划让人愿意参与的内容"],["我喜欢","社区里的慢关系"],["我是什么样的人","现实主义的理想派"],["我希望认识什么样的人","认真考虑实体创业的人"]]'::jsonb,'[{"age":"35 岁","t":"广告公司创意总监","d":"做过很多品牌故事，却越来越想经营一个真实的公共空间。"},{"age":"40 岁","t":"开设社区书店","d":"用活动策划和会员制降低单纯卖书的经营风险。"}]'::jsonb),
  (12,'远山灯塔','灯',0,false,'工程师转产品营销后，我才发现解释技术不是降维，而是另一种专业。','后端工程师 → 产品营销',ARRAY['技术转市场','产品营销','32 岁']::text[],'[["我擅长","把技术讲成人能理解的价值"],["我喜欢","连接产品与市场"],["我是什么样的人","外向的工程师"],["我希望认识什么样的人","想从技术走向业务的人"]]'::jsonb,'[{"age":"26 岁","t":"后端工程师","d":"喜欢技术，也常常主动给客户解释复杂功能。"},{"age":"32 岁","t":"转型产品营销","d":"从技术布道切入，负责开发者产品的定位、内容和上市。"}]'::jsonb)
insert into traveler_details (traveler_id,age,city,from_role,to_role,years,intro,full_text,advice,result,consulted,response_time) values
  (1,33,'杭州','交互设计','AI 产品经理','转型 5 年','我在 28 岁时开始尝试转型 AI 产品。没有裸辞，也没有把过去全部推倒重来，而是利用下班时间学习和实践，在公司申请小型 AI 项目，逐步承担更多产品职责。30 岁完成内部转岗，后来跳到互联网公司，现在负责 AI 产品方向。','真正的转折不是拿到产品经理的 title，而是第一次独立为结果负责。设计经验让我更懂用户，但商业判断、数据意识和跨团队推进都需要从零补课。前一年我做了 47 次用户访谈，把每次失败都整理成可复用的判断框架。回头看，最有效的路径不是囤课，而是尽早进入一个真实项目。','{"decision":["先用一个 6 周的小项目验证兴趣，不急着辞职。","把“想转型”改成一个可验证的问题：我愿不愿意持续为结果负责？","至少找 3 位真实从业者，问清工作中最消耗人的部分。"],"ability":["把用户研究、信息架构和原型能力翻译成产品语言。","刻意补齐数据分析、商业判断和项目推进三项短板。","作品集不要只放界面，要讲清目标、取舍和结果。"],"interview":["准备一个你真正推动过的项目，而不是包装出的完整案例。","回答冲突题时说明你如何建立共同目标。","主动展示对 AI 能力边界与失败场景的理解。"]}'::jsonb,'5 年完成转型，未出现明显降薪',42,'通常 4 小时内回复'),
  (2,32,'南京','互联网运营','心理学在读','重启 2 年','30 岁重新走进本科课堂，我并不比别人更勇敢，只是终于承认继续待在熟悉的工作里会越来越空。决定重读本科之前，我用半年做财务准备，也和家人反复沟通。','最难的是接受自己重新成为新手。课程、实习和经济压力同时出现时，我把目标缩小到每周能完成的动作，并保留一份远程兼职。稳定感没有消失，只是从职位变成了自己可执行的节奏。','{"decision":["先计算能支撑多久，而不是只问自己敢不敢。","试听真实课程，确认喜欢的是学科还是想象。","提前设计与家人的沟通边界。"],"ability":["把运营中的沟通与洞察迁移到访谈训练。","保持每周复盘，建立长期学习节奏。","尽早进入真实实习场景。"],"interview":["诚实解释重启原因，不必把每一步合理化。","用行动证据说明你的长期投入。","准备面对年龄相关问题的稳定表达。"]}'::jsonb,'边读书边维持远程收入',27,'通常当天回复'),
  (3,29,'厦门','大厂运营','间隔年探索','Gap 第 1 年','裸辞后的前两个月，我仍然每天打开招聘软件。后来开始环岛骑行，才意识到休息不是为了更快回到原轨道，而是重新听见自己的节奏。','存款减少会制造真实焦虑，所以我给这段间隔年设置了预算上限、复盘节点和退出条件。第三个月之后，我开始用短项目换住宿，也重新接触写作。没有得到标准答案，但知道下一份工作不能再以透支身体为代价。','{"decision":["为 Gap 设置预算上限和最晚复盘日。","区分“逃离现在”和“走向新的方向”。","在离职前处理保险、现金流和居住问题。"],"ability":["用小项目保持工作手感。","记录精力变化，找到真正恢复你的活动。","建立低成本生活系统。"],"interview":["不回避空窗期，说明你完成了哪些探索。","把零散经历组织成选择逻辑。","明确下一份工作的底线。"]}'::jsonb,'睡眠恢复，重新建立生活节奏',18,'通常 8 小时内回复'),
  (4,31,'成都','视觉设计','独立开发','独立第 2 年','我没有等到技术完全准备好才开始。第一款产品用了三周上线，几乎没人付费；第二款也失败了。第三款小工具终于覆盖房租。','一个人做产品最重要的不是全栈，而是知道什么暂时不做。设计背景帮我快速做出体验，但真正让产品活下来的是持续访谈、定价实验和克制功能范围。','{"decision":["先做能在两周内交付的最小版本。","上线前找到 10 个真实潜在用户。","给自己设定可承受的试错预算。"],"ability":["学会用低代码和 AI 补足开发环节。","把定价当成产品设计的一部分。","建立每周固定的用户反馈节奏。"],"interview":["独立开发经历要用数据说明。","解释你主动砍掉了什么。","展示从失败版本到当前版本的变化。"]}'::jsonb,'第三款产品开始覆盖房租',35,'通常 6 小时内回复'),
  (5,37,'上海','产品经理','心理咨询师','转型 3 年','35 岁开始系统学习心理咨询时，我的时薪从 500 变成 0。那段时间最难的不是收入，而是接受新的职业身份需要慢慢长出来。','我保留了一部分产品顾问工作，用三年完成课程、督导和实习。过去的产品经验让我善于结构化问题，但咨询训练要求我放下解决问题的冲动，真正听见对方。','{"decision":["先体验真实课程和个人咨询。","预留至少两年的训练时间。","不要低估督导与个人成长成本。"],"ability":["练习倾听，不急着给建议。","建立稳定的案例记录与督导机制。","把结构化能力用于整理，而不是控制对话。"],"interview":["说明转型中的持续训练证据。","坦诚面对经验时数。","把过去职业经验转化成理解人的能力。"]}'::jsonb,'完成实习，开始稳定接案',31,'通常当天回复'),
  (6,33,'深圳','管理咨询','用户研究','转型 2 年','在咨询公司做了四年行业研究和高管访谈后，我发现自己真正着迷的是访谈里具体的人，而不是 PPT 里抽象的市场。31 岁转型用户研究，把最擅长的访谈和结构化分析原样带了过来，只是服务对象从甲方变成了产品。','转型时最大的心理关卡是头衔落差：从给 CEO 汇报变成给产品经理提供输入。前六个月我刻意补了两件事：一是学会把研究结论翻译成可执行的产品建议，而不是交付一份漂亮报告；二是接受研究只是决策输入之一，结论被推翻是常态。咨询训练出的假设驱动和快速拆解，在互联网里依然是稀缺能力，真正要换掉的是交付心态。','{"decision":["先分清你喜欢的是「研究」还是「咨询的光环」，两者的日常完全不同。","用一次真实的用户访谈项目试水，再决定是否离开咨询。","接受第一份研究岗位的头衔和薪资可能回调，把它当学费。"],"ability":["把行业分析框架转译成用户研究计划，方法论是通用的。","补齐问卷设计与定量分析，咨询背景的人常常只擅长定性。","练习把研究结论写成一页纸的产品建议，而非四十页报告。"],"interview":["准备一个「研究改变了产品决策」的完整案例。","说明你如何面对结论被挑战，而不是只讲方法严谨。","展示对业务指标的理解，研究岗最怕被当成学院派。"]}'::jsonb,'2 年完成转型，现负责一条产品线的用户研究',23,'通常当天回复'),
  (7,36,'大理','互联网运营','民宿主理人','经营 2 年','29 岁做到大厂运营负责人，34 岁搬到大理开民宿。离开不是冲动：我提前一年做了预算表，算清了改造成本、淡旺季现金流和最坏情况下的退路，才递的辞职信。','第一年是真实的祛魅期：选址谈租约、盯装修、通下水道、半夜接投诉，运营大盘的方法论帮不上忙，但大厂练出的用户思维和内容能力成了获客的核心——我的客源七成来自自己写的内容。第二年才开始谈得上生活方式：收入大约是原来的四成，但时间和情绪是自己的。如果你把小城生活当逃离，大概率会失望；把它当一门要认真经营的小生意，它才养得活你。','{"decision":["先按最坏情况做十二个月现金流测算，再决定要不要离开。","保留一项可远程的技能或副业，作为回不去时的缓冲。","先以旅居方式住满三个月，再考虑签长租约。"],"ability":["把运营的内容和用户思维迁移到获客，小生意最缺的就是这个。","学会看租约、算毛利、盯施工，这些没人替你做。","建立本地的手艺人与供应商网络，比线上流量更救急。"],"interview":["如果考虑回大城市，把经营民宿讲成完整的业务操盘经历。","用数据说明你独立完成了获客、定价和复购。","坦诚说明离开的原因和这两年的取舍，不要包装成度假。"]}'::jsonb,'民宿第二年实现盈利，客源七成来自自有内容',29,'通常 8 小时内回复'),
  (8,29,'广州','财务分析','数据分析师','转型 2 年','我没有裸辞去报班，而是先把财务共享中心里没人愿意整理的报表数据变成了自动化脚本和第一个数据项目。27 岁在原公司完成内部转岗，路径慢，但几乎没有风险。','转岗第一年最难的不是技术，而是把「会写 SQL」变成「能回答业务问题」。我给自己定了一个标准：每个分析都要指向一个可执行的决策建议。财务背景反而成了优势——我天然懂成本结构和利润口径，很多纯技术背景的分析师要花一年才补上。作品集全部来自公司真实数据的脱敏版本，面试时比任何证书都有说服力。','{"decision":["优先评估内部转岗的可能性，它比裸辞学习风险低得多。","把「想转数据」拆成一个可验证的小项目，先做再说。","观察目标岗位的日常，确认你喜欢的是分析而不是想象中的高薪。"],"ability":["SQL 和一门脚本语言是底线，但业务理解才是差异化。","用自动化解决自己手头的重复工作，就是最好的第一个项目。","作品集讲清业务问题、分析过程和落地结果，不要堆技术名词。"],"interview":["准备一个「分析改变了业务动作」的案例，哪怕很小。","财务背景要主动讲成对指标口径的天然优势。","被问基础技术题时诚实说边界，再展示学习速度。"]}'::jsonb,'内部转岗成功，薪资持平，第二年开始带数据专项',38,'通常 4 小时内回复'),
  (9,38,'北京','全职妈妈','生涯咨询师','重返 2 年','30 岁暂停工作照顾家庭，36 岁重新出发成为生涯咨询师。重返职场时我没有隐藏那五年，而是把它讲成真实的能力：多线程协调、预算管理、和在极度受限条件下保持行动。','最难的不是技能生疏，而是自我怀疑：简历上的五年空白像一道要不断解释的伤口。转机是我把「解释空白」变成「陈述能力」——五年里我组织过社区互助小组、管理过家庭的全部财务，这些都是真实的项目经验。选择生涯咨询也不是退而求其次：我系统读完了课程、完成督导时数，从同伴互助个案做起。现在我的来访者一半是重返职场的女性，那五年成了我最重要的专业资产。','{"decision":["重返的方向不必是原岗位，先盘点这几年真实长出的能力。","给自己六个月的过渡期预算，降低「必须马上成功」的压力。","和家人明确重返后的分工边界，否则会被默认状态拖回去。"],"ability":["把育儿期的协调、预算、危机处理翻译成职场语言。","选一个有系统训练和认证路径的方向，让投入可见。","从低价或公益个案开始积累案例，不要等「准备好」。"],"interview":["主动、平静地讲空白期，你越坦然，对方越放心。","用具体事例证明你的多线程协调能力。","准备好回答「会不会再次离开」，给出真实的边界安排。"]}'::jsonb,'完成认证并稳定接案，来访者以重返职场女性为主',26,'通常当天回复'),
  (10,31,'上海','建筑设计','UX 设计师','转型 2 年','在建筑事务所画了五年图，习惯了三年才能落成的项目，也厌倦了永远等不到的用户反馈。29 岁用半年时间做了三个真实数字产品项目，转型 UX，现在负责一家 SaaS 的企业端体验。','建筑转 UX 最大的红利是处理复杂约束的能力：动线、规范、结构、预算之间的权衡，和企业软件里角色、权限、流程的纠缠是同构的。最大的坑是节奏——建筑的严谨会让你想把方案打磨到完美再拿出来，而数字产品要求你先拿半成品去验证。作品集我没有做概念图，而是找了两个真实小企业和一个开源项目做免费改版，每个案例都有上线前后的对比。这三个项目就是我的敲门砖。','{"decision":["先用业余时间完成一个真实项目，验证你喜欢的是设计还是逃离建筑。","算清收入回调的幅度和恢复周期，UX 起薪可能低于你的年资。","关注企业级产品方向，建筑背景在复杂系统里最有优势。"],"ability":["把空间叙事能力转译成信息架构和用户流程。","补齐可用性测试和数据意识，学会用反馈代替直觉。","作品集要真实项目加上线结果，概念稿说服不了面试官。"],"interview":["用建筑案例讲清你如何在多重约束下做取舍。","展示快速迭代的作品，打消「建筑背景节奏慢」的疑虑。","说明你理解数字产品的协作方式，设计不再是最终交付物。"]}'::jsonb,'半年三个真实项目完成转型，现负责企业端体验',33,'通常 6 小时内回复'),
  (11,42,'苏州','广告策划','独立书店主理人','经营 2 年','做了十五年广告，35 岁当上创意总监，40 岁开了社区书店。这不是浪漫冲动：我用一年时间算清了租金、库存周转和现金流，确认单纯卖书活不下来之后，才设计了会员制加活动策划的模式。','书店第一年的真相是：卖书的毛利撑不起房租，真正养活书店的是会员制、场地活动和策展合作——而这些恰恰是我做了十五年的老本行。广告训练出的能力没有浪费：给品牌讲故事变成给社区做内容，提案变成活动策划，比稿变成谈异业合作。最大的心态转变是从「大预算大曝光」回到「一场活动来三十个人」的尺度，但这三十个人我叫得出名字。实体创业不是逃离职场，它是把你的全部专业能力押在一个更小但更真实的场景里。','{"decision":["先算账再谈情怀：租金、库存、人力，按最坏情况算十八个月。","确认你的老本行能否成为新生意的差异化，而不是从零开始。","用快闪或市集先试三个月，验证选品和社区反应。"],"ability":["把内容和策划能力变成书店的经营核心，卖书只是入口。","学会库存管理和现金流表，创意人最容易死在账上。","经营社区关系，回头客和会员才是实体店的护城河。"],"interview":["如果重回职场，把开店讲成完整的小生意操盘经历。","用数据讲清你如何用有限预算获客和留存。","展示从服务甲方到直接面对用户的视角变化。"]}'::jsonb,'书店第二年靠会员与活动实现收支平衡',21,'通常当天回复'),
  (12,34,'北京','后端工程师','产品营销','转型 2 年','写了六年后端，我发现自己最兴奋的时刻不是上线，而是给客户讲清楚这个功能为什么值得用。32 岁从技术布道切入转型产品营销，现在负责一条开发者产品线的定位、内容和上市。','技术转市场最反直觉的一课是：解释技术不是降维，而是另一门专业。写代码时我以为「讲清楚」是天赋，做营销后才明白定位、叙事、渠道各有方法论，要像当年学算法一样系统补课。工程师背景给了我两个真实优势：开发者受众能一眼识别你是不是自己人；我能直接读代码和文档，内容不需要二手转译。转型路径上，技术布道是最平滑的跳板——一半时间写代码做 demo，一半时间做内容和演讲，让我在不离开技术的情况下验证了自己真的喜欢面向人的工作。','{"decision":["先在现岗位争取写文档、做分享的机会，验证你是否享受表达。","考虑技术布道或开发者关系作为过渡，不必一步跳到营销。","想清楚放弃技术晋升通道的机会成本，转回去会越来越难。"],"ability":["系统学习定位和内容方法论，别靠「我懂技术」硬写。","把 demo、文档和演讲变成作品集，这是技术背景独有的证据。","补齐渠道和数据侧知识，营销不只是写得好。"],"interview":["准备一个「技术内容带来真实增长」的案例。","展示你能在工程和市场两种语言之间双向翻译。","说明你理解营销的被衡量方式，别只谈热爱表达。"]}'::jsonb,'经技术布道完成转型，现负责开发者产品营销',25,'通常 6 小时内回复')
insert into traveler_services (id,traveler_id,kind,title,price,unit,description,tags) values
  ('consult',null,'1 对 1 咨询','针对你的具体问题深聊',29,'/ 小时','围绕转型选择、能力差距、作品集或求职准备，结合亲历给出针对性建议。',ARRAY['实时文字沟通','1 小时','24 小时内可追问']::text[]),
  ('materials',null,'资料工具包','海外学校申请材料包',9.9,'','包含选校比较表、申请时间线、文书自查清单和材料命名模板，购买后即可查看。',ARRAY['4 份模板','申请清单','永久查看']::text[]),
  ('companion',null,'阶段陪跑','申请陪跑服务',599,'/ 期','从目标拆解到材料提交的 4 周陪跑，每周复盘进度并提供关键节点反馈。',ARRAY['4 周','每周复盘','材料反馈']::text[]),
  ('consult-t6',6,'1 对 1 咨询','咨询转用户研究路径复盘',39,'/ 小时','结合行业研究与访谈经验，帮你评估从咨询/分析岗转用户研究的可行路径与作品集准备。',ARRAY['实时文字沟通','1 小时','24 小时内可追问']::text[]),
  ('consult-t7',7,'1 对 1 咨询','小城开店与现金流测算',35,'/ 小时','从选址、改造预算到淡旺季现金流，用真实经营数据帮你把「想去小城生活」算成一笔明白账。',ARRAY['实时文字沟通','1 小时','含测算模板']::text[]),
  ('materials-t8',8,'资料工具包','内部转岗数据作品集清单',12.9,'','包含自动化脚本选题清单、业务分析案例框架和转岗沟通话术，帮你用现有工作数据低风险转型。',ARRAY['3 份模板','案例框架','永久查看']::text[]),
  ('consult-t9',9,'1 对 1 咨询','重返职场节奏规划',29,'/ 小时','面向职业空白期后的重启：盘点隐性能力、设计过渡期节奏，并演练空白期的面试表达。',ARRAY['实时文字沟通','1 小时','24 小时内可追问']::text[]),
  ('materials-t10',10,'资料工具包','UX 转型作品集自查表',15.9,'','包含真实项目选题思路、作品集结构自查清单和常见面试追问整理，适合传统设计背景转数字产品。',ARRAY['3 份模板','自查清单','永久查看']::text[]),
  ('companion-t11',11,'阶段陪跑','实体开店筹备 4 周陪跑',499,'/ 期','从算账、选址评估到开业活动策划的 4 周陪跑，每周复盘一次，帮你在签约前把风险想清楚。',ARRAY['4 周','每周复盘','预算模板']::text[]),
  ('consult-t12',12,'1 对 1 咨询','技术转市场定位梳理',32,'/ 小时','帮技术背景的你评估布道/营销转型路径，梳理个人定位并规划第一批内容作品。',ARRAY['实时文字沟通','1 小时','24 小时内可追问']::text[])
insert into bounties (id,question,reward,responses,tags,detail) values
  (1,'有没有人从设计转数据分析？想听第一年最难的是什么','¥29 悬赏','12 人回应',ARRAY['职业转型','数据分析','设计背景']::text[],'我做了 4 年视觉设计，最近在自学 SQL 和 Python。真正担心的不是课程学不会，而是没有数据项目经验，也不知道第一份工作是否一定会降薪。希望听到设计背景转数据分析的真实经历，尤其是入行第一年的困难和准备方式。'),
  (2,'26 岁要不要辞职考研？家里催我先稳定下来','¥19.9 悬赏','31 人回应',ARRAY['升学选择','辞职考研','家庭沟通']::text[],'目前工作两年，收入稳定但看不到想要的发展。想跨专业读心理学研究生，家里认为先工作、结婚更现实。我希望了解辞职备考的现金流压力、失败后的退路，以及怎样和家人沟通。'),
  (3,'想去小城市生活，又怕后悔，有回不来的人吗？','¥39 悬赏','8 人回应',ARRAY['城市迁移','生活方式','小城创业']::text[],'在上海做运营第 6 年，越来越想搬去生活成本低、节奏慢一点的城市。但担心收入、社交圈和以后回大城市的难度。想听已经搬走两年以上的人讲讲真实得失，而不只是旅行滤镜。')
